// Launch Params: the launch row is the contract. Client (resolves the base), View (a People view by
// name, required) and Max Rows: how many people Blitz may be asked in this run, one credit each,
// for the people GetLeads does not answer. Blank or 0 means GetLeads only, which costs no cash.
// Table is implied (People); a filled Table that is not People is refused.
//
// REFUSALS: a badly filled row is an expected outcome, not a crash. Every guard returns a refusal
// item (`refused` carries the reason); Launch OK? routes it to Build Refusal, which closes the row
// Failed with the reason. Nothing is read or asked before the guards pass.
const rec=$('Fetch Launch Record').first().json||{};
const f=rec.fields||{};
const cf=(($('Resolve Base').first().json||{}).fields)||{};
const base=String(cf['Clayroots Base ID']||'').trim();
const arr=(v)=>Array.isArray(v)?v:(v==null||v===''?[]:[v]);
const clientRecId=(arr(f['Client']).map(x=>(x&&typeof x==='object')?x.id:x)[0])||'';
const table=String(f['Table']||'').trim();
const view=String(f['View']||'').trim();
const maxRaw=f['Max Rows'];
const maxBlitz=(maxRaw===undefined||maxRaw===null||maxRaw==='')?0:Math.max(0,Math.floor(Number(maxRaw)||0));
const startedAt=new Date().toISOString();
const where='Launch record '+(rec.id||'?');
const p={ refused:'', base, clientRecId, table:'People', view, maxBlitz, trigger:'form', _launchRecordId:rec.id||'', startedAt };
const refuse=(r)=>[{ json:Object.assign({},p,{ refused:r, table:table||'People' }) }];
if(!clientRecId) return refuse(where+' has no Client link. Nothing was asked.');
if(!/^app[A-Za-z0-9]{14}$/.test(base)) return refuse('Client on '+where.toLowerCase()+' has no valid Clayroots Base ID. Nothing was asked.');
if(table&&table.toLowerCase()!=='people') return refuse(where+' names Table "'+table+'". A profile belongs to a person, so this machine runs on People only. Nothing was asked.');
if(!view) return refuse(where+' has no View. A People view is required by name. Nothing was asked.');
return [{ json:p }];

// Event Params: the record door. Any caller may POST {baseId, clientRecordId, view, maxRows}; the
// same contract as the launch row, the same refusals, no launch row and no Running stamp (the
// close creates the run row on Execution ID). The door answers 200 on receipt and the run carries
// on alone.
const b=($input.first().json||{}).body||{};
const s=(v)=>String(v==null?'':v).trim();
const base=s(b.baseId||b.base);
const table=s(b.table)||'People';
const view=s(b.view);
const maxBlitz=Math.max(0,Math.floor(Number(b.maxRows||b.max_rows||b.maxBlitz)||0));
const startedAt=new Date().toISOString();
const p={ refused:'', base, clientRecId:s(b.clientRecordId||b.clientRecId), table:'People', view, maxBlitz, trigger:'event', _launchRecordId:'', startedAt };
const refuse=(r)=>[{ json:Object.assign({},p,{ refused:r, table }) }];
if(!/^app[A-Za-z0-9]{14}$/.test(base)) return refuse('Record door: no valid baseId in the body. Nothing was asked.');
if(table.toLowerCase()!=='people') return refuse('Record door: Table "'+table+'" is not People. Nothing was asked.');
if(!view) return refuse('Record door: no view in the body. Nothing was asked.');
return [{ json:p }];

// Params: one shape for both entries. Whichever entry ran wrote its item; this re-emits it so every
// node after reads $('Params') and never cares which door opened the run.
let p=null;
try{ p=$('Launch Params').first().json; }catch(e){}
if(!p||(!p.base&&!p.refused)){ try{ p=$('Event Params').first().json; }catch(e){} }
if(!p) throw new Error('Enrich Person Profile: no entry produced launch parameters.');
return [{ json:p }];

// Resolve Table: People by name in the base meta just read, the view by name or id. A base without
// People or without the view is refused on the row (Table OK? routes to Build Refusal). Field names
// and types travel for the column check. Nothing here creates.
const p=$('Params').first().json;
const r=$input.first().json||{}; const body=(r.body!==undefined)?r.body:r;
const tables=(body&&Array.isArray(body.tables))?body.tables:null;
const refuse=(why)=>[{ json:{ refused:why } }];
if(!tables) return refuse('Could not read the table list for base '+p.base+': '+JSON.stringify(body).slice(0,200)+'. Nothing was asked.');
const t=tables.find(x=>String(x.name||'').trim().toLowerCase()==='people');
if(!t) return refuse('Base '+p.base+' has no People table. Nothing was asked.');
const v=(t.views||[]).find(x=>x.id===p.view||String(x.name||'').trim()===p.view);
if(!v) return refuse('People ('+t.id+') in base '+p.base+' has no view "'+p.view+'". Nothing was asked.');
const types={}; for(const f of (t.fields||[])) types[f.name]=f.type;
return [{ json:{ refused:'', tableId:t.id, tableName:t.name, viewId:v.id, viewName:v.name, fieldNames:(t.fields||[]).map(f=>f.name), fieldTypes:types } }];

// Check Columns: what a person row must carry (Name, Domain, and at least one of LinkedIn URL,
// Email, first_name; written by Enrich Contacts) and the eleven profile columns this machine
// fills, the same eleven Enrich Contacts brings: Headline, About, Role Description, Role Start
// Date, Person City, Person Country, Education, Skills, Languages, Prior Employer, Prior Title.
// Created on first use when People lacks them; a column at a compatible type is used as is; a
// column at a foreign type refuses the launch on the row. Nothing is retyped or renamed. Also
// emits the field list the row read asks for, so a 40,000-row view stays light.
const p=$('Params').first().json;
const t=$('Resolve Table').first().json;
const have=t.fieldTypes||{};
const refuse=(why)=>[{ json:{ refused:why } }];
for(const need of ['Name','Domain','Contact Key']){ if(!(need in have)) return refuse('People ('+t.tableId+') in base '+p.base+' has no '+need+' column. Enrich Contacts owes it. Nothing was asked.'); }
const PROFILE=[
  { name:'Headline', type:'singleLineText' },
  { name:'About', type:'multilineText' },
  { name:'Role Description', type:'multilineText' },
  { name:'Role Start Date', type:'date', options:{ dateFormat:{ name:'iso' } } },
  { name:'Person City', type:'singleLineText' },
  { name:'Person Country', type:'singleLineText' },
  { name:'Education', type:'multilineText' },
  { name:'Skills', type:'multilineText' },
  { name:'Languages', type:'multilineText' },
  { name:'Prior Employer', type:'singleLineText' },
  { name:'Prior Title', type:'singleLineText' }
];
const FAMILY={ singleLineText:['singleLineText','multilineText','richText'], multilineText:['multilineText','singleLineText','richText'], date:['date','dateTime'] };
const clash=PROFILE.filter(f=>(f.name in have)&&FAMILY[f.type].indexOf(have[f.name])<0);
if(clash.length) return refuse('People ('+t.tableId+') in base '+p.base+' already holds '+clash.map(f=>'"'+f.name+'" as '+have[f.name]+' (this machine writes it as '+f.type+')').join(', ')+'. A column at another type is not this machine\'s to write; rename or retype it by hand. Nothing was asked.');
const toCreate=PROFILE.filter(f=>!(f.name in have));
const url='https://api.airtable.com/v0/meta/bases/'+p.base+'/tables/'+t.tableId+'/fields';
const optional=['first_name','last_name','Email','Final Email','LinkedIn URL'].filter(n=>n in have);
return [{ json:{ refused:'', base:p.base, tableId:t.tableId, profileFields:PROFILE.map(f=>f.name), toCreate:toCreate.map(f=>f.name), creates:toCreate.map(f=>({ url, body:{ name:f.name, type:f.type, options:f.options } })), fetchFields:['Name','Domain','Contact Key'].concat(optional,['Headline','Person City','Person Country']), heldFields:['Name','Domain','Contact Key'].concat(optional,PROFILE.map(f=>f.name)) } }];

// Plan Columns: one meta-API call per profile column People lacks. Runs only when there is
// something to create; the IF before it routes an empty plan straight to the row read.
const c=$('Check Columns').first().json;
return (c.creates||[]).map(x=>({ json:x }));

// Verify Columns: the base meta read again after the creates. Every profile column must now show
// on People; anything still missing stops the run by name before a row is read (a crash here is a
// real defect: the meta API accepted a create it did not perform).
const c=$('Check Columns').first().json;
const r=$input.first().json||{}; const body=(r.body!==undefined)?r.body:r;
const tables=(body&&Array.isArray(body.tables))?body.tables:null;
if(!tables) throw new Error('Could not re-read the table list for base '+c.base+' after creating columns on People: '+JSON.stringify(body).slice(0,200)+'. Nothing was asked.');
const names=new Set((((tables.find(t=>t.id===c.tableId))||{}).fields||[]).map(f=>f.name));
const still=(c.toCreate||[]).filter(n=>!names.has(n));
if(still.length){ let why=''; try{ why=$('Create Columns').all().map(i=>JSON.stringify(i.json).slice(0,200)).join(' | '); }catch(e){} throw new Error('Enrich Person Profile created columns People does not show: '+still.join(', ')+'. Airtable answered: '+why+'. Nothing was asked.'); }
return [{ json:{ created:(c.toCreate||[]).slice() } }];

// Pack Rows: the view's rows become the ask. A row already carrying Headline, Person City and
// Person Country is complete for this machine's purpose and is skipped (counted); a row with no
// Name or no Domain cannot be looked up and is skipped (counted). Every row kept carries the run
// context the batch sub-execution needs (Params and Resolve Table do not exist inside it). One
// row = one person to look up. The skip counts ride on every row so the batch log can show them.
const p=$('Params').first().json;
const t=$('Resolve Table').first().json;
const c=$('Check Columns').first().json;
const rows=$input.all().map(i=>i.json).filter(j=>j&&j.id);
const one=(v)=>String(Array.isArray(v)?(v[0]||''):(v==null?'':v)).trim();
const st={ inView:rows.length, complete:0, noKey:0, asked:0 };
const keep=[];
for(const r of rows){
  const f=r.fields||{};
  if(one(f.Headline)&&one(f['Person City'])&&one(f['Person Country'])){ st.complete++; continue; }
  if(!one(f.Name)||!one(f.Domain)){ st.noKey++; continue; }
  st.asked++;
  keep.push({ id:r.id });
}
const ctx={ _baseId:p.base, _tableId:t.tableId, _tableName:t.tableName, _view:t.viewName, _execId:String($execution.id), _startedAt:p.startedAt, _clientId:p.clientRecId||'', _trigger:p.trigger||'form', _total:st.asked, _inView:st.inView, _complete:st.complete, _noKey:st.noKey, _maxBlitz:p.maxBlitz||0, _heldFields:c.heldFields||[], _profileFields:c.profileFields||[] };
if(!keep.length) return [{ json:Object.assign({ _empty:true }, ctx) }];
return keep.map(j=>({ json:Object.assign({}, j, ctx) }));

// Build Log: the run's final row. The batches accumulated their counters in this row's Tally (each
// sub-execution reads the row, adds its slice, writes it back with Status Running); this pass reads
// the accumulated Tally once more and writes the verdict. A run with no rows writes its trace too.
const p=$('Params').first().json;
let t={}; try{ t=$('Resolve Table').first().json||{}; }catch(e){}
let c={}; try{ c=$('Check Columns').first().json||{}; }catch(e){}
let pack={}; try{ pack=$('Pack Rows').first().json||{}; }catch(e){}
const n=(v)=>Number(v)||0;
const inView=n(pack._inView), complete=n(pack._complete), noKey=n(pack._noKey), total=n(pack._total);
const BLANK={ rows:0, answered:0, unanswered:0, filled:0, cells:0, byGetLeads:0, byBlitz:0, glCalls:0, glReturned:0, glMatched:0, glStrangers:0, glErrors:0, glNoKey:0, glBudget:false, blitzCalls:0, blitzFound:0, blitzNotFound:0, blitzErrors:0, blitzNoEmail:0, blitzCapped:0, written:0, writeErrors:0, writeWhy:[], failWhy:[], batches:0 };
let a=Object.assign({},BLANK);
try{ const prior=$('Read Run Row').first().json; const raw=prior&&prior.fields?prior.fields.Tally:null; if(raw){ const parsed=JSON.parse(String(raw)); if(parsed&&String(parsed.execId)===String($execution.id)) a=Object.assign({},BLANK,parsed); } }catch(e){}
let dur=0; try{ dur=Math.max(0,Math.round(($now.toMillis()-new Date(p.startedAt).getTime())/1000)); }catch(e){}
const created=(c.toCreate||[]);
const lines=[
  '**'+n(a.rows)+' people looked up, '+n(a.answered)+' found, '+n(a.filled)+' rows filled ('+n(a.cells)+' cells), '+n(a.unanswered)+' not found**',
  '',
  '**Scope:** one client, People view "'+(t.viewName||p.view)+'", '+inView+' rows in the view, '+total+' asked in '+n(a.batches)+' batches of 100',
  '**Rule:** GetLeads first, one lookup per person by email, LinkedIn URL or name at the domain, an answer kept only when it proves the same person; Blitz by email for the misses, one credit each, up to Max Rows ('+n(p.maxBlitz)+'). Blanks filled on the held row, nothing overwritten, no new rows.',
  '',
  '**Results**',
  '- **Filled by:** GetLeads '+n(a.byGetLeads)+', Blitz '+n(a.byBlitz),
  '- **GetLeads:** '+n(a.glCalls)+' lookups ('+n(a.glReturned)+' rows on fair use), '+n(a.glMatched)+' matched, '+n(a.glStrangers)+' strangers dropped'+(n(a.glErrors)?', '+n(a.glErrors)+' errors':'')+(a.glBudget?'; fair-use budget hit':''),
  '- **Blitz:** '+n(a.blitzCalls)+' asked ('+n(a.blitzCalls)+' credits), '+n(a.blitzFound)+' found, '+n(a.blitzNotFound)+' not found'+(n(a.blitzCapped)?', '+n(a.blitzCapped)+' held back by the cap':'')+(n(a.blitzNoEmail)?', '+n(a.blitzNoEmail)+' had no email to ask with':''),
  '- **Rows written (confirmed by Airtable):** '+n(a.written)+(n(a.writeErrors)?', '+n(a.writeErrors)+' refused':''),
  '- **Columns created on first use:** '+(created.length?created.join(', '):'none (already there)')
];
const skips=[];
if(complete) skips.push(complete+' rows already carrying Headline, Person City and Person Country');
if(noKey) skips.push(noKey+' rows with no Name or no Domain');
if(n(a.glNoKey)) skips.push(n(a.glNoKey)+' rows with no email, LinkedIn URL or full name to look up');
if(!inView) skips.push('the view had no rows');
if(skips.length) lines.push('', '**Skipped ('+skips.join('; ')+')**');
const fails=[].concat((a.failWhy||[]).map(x=>'lookup: '+x), (a.writeWhy||[]).map(x=>'write: '+x));
const failed=n(a.glErrors)+n(a.blitzErrors)+n(a.writeErrors);
if(fails.length){ lines.push('', '**Failures ('+failed+')**'); for(const x of fails.slice(0,12)) lines.push('- '+x); }
const log={
  'Execution ID': String($execution.id),
  'Automation': 'Enrich Person Profile',
  'Status': failed?'Succeeded with errors':'Succeeded',
  'Trigger': p.trigger||'form',
  'Errors': failed,
  'Run at': p.startedAt,
  'Target': (t.tableName||'People')+' ('+(t.tableId||'')+')',
  'View': t.viewName||p.view,
  'Records In': inView,
  'Records Out': n(a.written),
  'Duration s': dur,
  'Description': lines.join('\n'),
  'Tally': JSON.stringify(Object.assign({}, a, { execId:String($execution.id), inView, complete, noKey, total })).slice(0,90000),
  'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id
};
if(p.clientRecId) log['Client']=[p.clientRecId];
return [{ json:log }];

// Build Refusal: the row a refused launch writes. A refusal is an expected outcome, not a crash:
// Launch Params, Resolve Table or Check Columns named the reason instead of throwing, and this
// closes the row (already stamped Running with this Execution ID on a Hub launch) as Failed with
// the reason and the link. Nothing was asked and nothing was written.
const p=$('Params').first().json||{};
const reasonOf=(name)=>{ try{ const j=$(name).first().json||{}; return String(j.refused||''); }catch(e){ return ''; } };
const reason=reasonOf('Check Columns')||reasonOf('Resolve Table')||String(p.refused||'')||'the launch was refused and no reason was recorded';
const show=(v)=>(v===''||v===null||v===undefined||v===0)?'(empty)':String(v);
const lines=[
  '**Refused before anything ran: '+reason+'**',
  '',
  '**Scope:** '+(p.clientRecId?('one client ('+p.clientRecId+')'):'no client resolved')+', launch '+(p._launchRecordId||'(event call, no launch row)'),
  '',
  '**The launch row as this machine read it**',
  '- **Client:** '+show(p.clientRecId),
  '- **Clayroots Base ID:** '+(p.base||'(empty, or the Clients row could not be read)'),
  '- **Table:** '+show(p.table)+' (only "People" is accepted)',
  '- **View:** '+show(p.view),
  '- **Max Rows (Blitz cap):** '+show(p.maxBlitz),
  '',
  '**Failures (1)**',
  '- Launch guard: '+reason,
  '',
  'No provider was called and nothing was written to the client base.',
  'Fix the named field on the launch row, clear Execution ID, and the Airtable door will fire it again.'
];
let dur=0; try{ dur=Math.max(0,Math.round(($now.toMillis()-new Date(p.startedAt).getTime())/1000)); }catch(e){}
const log={
  'Automation':'Enrich Person Profile',
  'Status':'Failed',
  'Trigger': p.trigger||'form',
  'Errors': 1,
  'Run at': $now.toISO(),
  'Records In': 0,
  'Records Out': 0,
  'Duration s': dur,
  'Description': lines.join('\n'),
  'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
  'Execution ID': String($execution.id)
};
if(p.view) log['View']=p.view;
if(p.clientRecId) log['Client']=[p.clientRecId];
return [{ json: log }];

// Held Filters: the batch's people, one OR formula on RECORD_ID() for the full read of what each
// row already holds (the fill-blanks rule needs every profile value, not the light view read).
const ids=$('Read Records').all().map(i=>String((i.json||{}).id||'')).filter(Boolean);
if(!ids.length) return [{ json:{ formula:"RECORD_ID()=''" } }];
return [{ json:{ formula:'OR('+ids.map(id=>"RECORD_ID()='"+id+"'").join(',')+')' } }];

// GL Requests: one GetLeads search per person, the cheapest exact key first. Email address is an
// exact match (Final Email, else the first address in Email at the person's domain); a LinkedIn
// URL is a substring match on its slug; last resort is first name and last name at the domain,
// substring matches that narrow rather than identify, so the answer is re-checked by GL Match. The
// answer carries the profile columns. Every returned row is one fair-use row, never cash; limit 5
// keeps a loose name match from costing more than a handful. People with no key at all are
// carried in _stats and go to nobody.
const held=$('Read Held').all().map(i=>i.json||{}).filter(j=>j.id);
const one=(v)=>String(Array.isArray(v)?(v[0]||''):(v==null?'':v)).trim();
const norm=(d)=>one(d).toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/.*$/,'');
const slugOf=(u)=>{ const m=one(u).toLowerCase().match(/linkedin\.com\/in\/([^\/?#]+)/); return m?m[1].replace(/\/+$/,''):''; };
const splitEmails=(s)=>one(s).split(/[,;\s]+/).map(e=>e.trim().toLowerCase()).filter(e=>/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e));
const COLUMNS=['First Name','Last Name','Contact Full Name','Email','Contact LinkedIn URL','Company Domain','Work Email Domain','Profile Headline','About Me','Current Role Description','Current Role Start Date','Work City','Work Country Code','Education','Skills','Languages'];
const out=[]; const st={ people:held.length, byEmail:0, byLinkedin:0, byName:0, noKey:0 };
for(const h of held){
  const f=h.fields||{};
  const domain=norm(f.Domain);
  const emails=[one(f['Final Email']).toLowerCase()].concat(splitEmails(f.Email)).filter(e=>e&&domain&&(e.endsWith('@'+domain)||e.slice(e.lastIndexOf('@')+1).endsWith('.'+domain)));
  const slug=slugOf(f['LinkedIn URL']);
  const first=one(f.first_name), last=one(f.last_name);
  let body=null, how='';
  if(emails.length){ body={ email_address:emails[0], limit:5, offset:0, columns:COLUMNS }; how='email'; st.byEmail++; }
  else if(slug){ body={ linkedin_url:'linkedin.com/in/'+slug, limit:5, offset:0, columns:COLUMNS }; how='linkedin'; st.byLinkedin++; }
  else if(first&&last&&domain){ body={ domains:[domain], first_name:first, last_name:last, limit:5, offset:0, columns:COLUMNS }; how='name'; st.byName++; }
  else { st.noKey++; continue; }
  out.push({ json:{ id:h.id, domain, how, body } });
}
if(!out.length) return [{ json:{ _none:true, _stats:st } }];
out[0].json._stats=st;
return out;

// GL Match: the search answers (aligned to GL Requests by index; the node hands a failure over as
// {error}) -> at most one profile per person. A returned row is the person only when it proves it:
// the same email, the same LinkedIn slug, or the same cleaned first and last name at the same
// domain. Anything else is a stranger and is dropped. The profile columns are read the way Enrich
// Contacts reads them (GetLeads answers raw column names on JSON and labels elsewhere, so every
// field is read through a normalized key). One item out: { profiles:{ <rowId>: extra }, stats }.
// Never throws.
const errMsg=(e)=>{ if(!e) return 'call failed'; if(typeof e==='string') return e; return String((e.message||'')+' '+(e.description||'')).trim()||'call failed'; };
const first=$('GL Requests').first().json||{};
const st=Object.assign({ people:0, byEmail:0, byLinkedin:0, byName:0, noKey:0 }, first._stats||{}, { called:0, returned:0, matched:0, strangers:0, errors:0, credits:0, firstError:'', failReasons:[], noCredential:0, budget:false });
const profiles={};
if(first._none) return [{ json:{ profiles, stats:st } }];
const asks=$('GL Requests').all().map(i=>i.json||{}).filter(j=>!j._none);
let answers=[]; try{ answers=$('GL Search').all(); }catch(e){}
const held={}; for(const i of $('Read Held').all()){ const j=i.json||{}; if(j.id) held[j.id]=j.fields||{}; }
const one=(v)=>String(Array.isArray(v)?(v[0]||''):(v==null?'':v)).trim();
const nk=(s)=>String(s).toLowerCase().replace(/[^a-z0-9]/g,'');
const pick=(row,cands)=>{ for(const c of cands){ const v=row[c]; if(v!==undefined&&v!==null&&String(v).trim()!==''&&String(v).trim()!=='N/A') return String(v).trim(); } return ''; };
const raw=(row,cands)=>{ for(const c of cands){ const v=row[c]; if(v!==undefined&&v!==null&&v!==''&&v!=='N/A') return v; } return null; };
const flat=(r)=>{ const o={}; for(const k of Object.keys(r||{})){ const v=r[k]; if(v&&typeof v==='object'&&!Array.isArray(v)){ for(const k2 of Object.keys(v)) o[nk(k2)]=v[k2]; } o[nk(k)]=v; } return o; };
const clip=(v,n)=>{ const t=String(v==null?'':v).trim(); return t.length>n?t.slice(0,n):t; };
// GetLeads writes the epoch (1970-01-01) where it has no date; anything before 1971 is no date.
const isoDate=(v)=>{ const m=String(v==null?'':v).trim().match(/^(\d{4}-\d{2}-\d{2})/); return (m&&Number(m[1].slice(0,4))>=1971)?m[1]:''; };
const parseVariant=(v)=>{ if(v==null) return []; if(typeof v==='string'){ const t=v.trim(); if(!t||t==='N/A') return []; if(/^[\[{]/.test(t)){ try{ v=JSON.parse(t); }catch(e){ return t.split(/[;|]\s*|,\s*/).map(x=>x.trim()).filter(Boolean); } } else return t.split(/[;|]\s*|,\s*/).map(x=>x.trim()).filter(Boolean); } if(Array.isArray(v)) return v; if(typeof v==='object') return [v]; return [String(v)]; };
const entry=(x,keys)=>{ if(x==null) return ''; if(typeof x!=='object') return String(x).trim(); const parts=[]; for(const k of keys){ const val=x[k]; if(val!=null&&String(val).trim()&&String(val).trim()!=='N/A') parts.push(String(val).trim()); } return parts.length?parts.join(', '):(x.name?String(x.name).trim():''); };
const joinVariant=(v,keys,sep)=>parseVariant(v).map(x=>entry(x,keys)).filter(Boolean).join(sep);
const cleanName=(s)=>String(s||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z]/g,'');
const slugOf=(u)=>{ const m=String(u||'').toLowerCase().match(/linkedin\.com\/in\/([^\/?#]+)/); return m?m[1].replace(/\/+$/,''):''; };
const splitEmails=(s)=>one(s).split(/[,;\s]+/).map(e=>e.trim().toLowerCase()).filter(e=>e.indexOf('@')>0);
const norm=(d)=>one(d).toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/.*$/,'');
answers.forEach((it,i)=>{
  const ask=asks[i]; if(!ask) return;
  st.called++;
  const j=it.json||{};
  if(j.error&&j.contacts===undefined){
    const msg=errMsg(j.error);
    if(/credential/i.test(msg)){ st.noCredential++; return; }
    if(/fair.?use|not enough credits|credits_exhausted|payment required|\b402\b/i.test(msg)){ st.budget=true; }
    st.errors++; const r='GetLeads: '+msg.slice(0,160); if(!st.firstError) st.firstError=r; if(st.failReasons.length<10) st.failReasons.push(r); return;
  }
  if(!Array.isArray(j.contacts)){ st.errors++; const r='GetLeads: '+String(j.message||'unreadable answer').slice(0,160); if(!st.firstError) st.firstError=r; if(st.failReasons.length<10) st.failReasons.push(r); return; }
  st.credits+=Number(j.query_credits_used)||0;
  const f=held[ask.id]||{};
  const myEmails=new Set([one(f['Final Email']).toLowerCase()].concat(splitEmails(f.Email)).filter(Boolean));
  const mySlug=slugOf(f['LinkedIn URL']);
  const myFirst=cleanName(f.first_name), myLast=cleanName(f.last_name), myDomain=norm(f.Domain);
  for(const rawRow of j.contacts){
    st.returned++;
    const r=flat(rawRow);
    const email=pick(r,['email','emailaddress','workemail']).toLowerCase();
    const slug=slugOf(pick(r,['contactlinkedinurl','linkedinurl','linkedin']));
    const rFirst=cleanName(pick(r,['firstname'])), rLast=cleanName(pick(r,['lastname']));
    const rDomain=norm(pick(r,['companydomain','domain','workemaildomain','emaildomain']))||(email.indexOf('@')>0?email.slice(email.lastIndexOf('@')+1):'');
    const proof=(email&&myEmails.has(email))||(slug&&mySlug&&slug===mySlug)||(myFirst&&myLast&&rFirst===myFirst&&rLast===myLast&&myDomain&&(rDomain===myDomain||rDomain.endsWith('.'+myDomain)));
    if(!proof){ st.strangers++; continue; }
    if(profiles[ask.id]) continue;
    profiles[ask.id]={
      'Headline':clip(pick(r,['profileheadline','linkedinheadline','headline']),500),
      'About':clip(pick(r,['aboutme','persondescription','about']),10000),
      'Role Description':clip(pick(r,['currentroledescription','jobdescription']),10000),
      'Role Start Date':isoDate(pick(r,['currentrolestartdate','jobstartdate'])),
      'Person City':clip(pick(r,['workcity','joblocationcity']),120),
      'Person Country':clip(pick(r,['workcountrycode','joblocationcountrycode']),8).toUpperCase(),
      'Education':clip(joinVariant(raw(r,['education']),['degree','field_of_study','field','school_name','school'],'; '),2000),
      'Skills':clip(joinVariant(raw(r,['skills']),['name','skill'],', '),2000),
      'Languages':clip(joinVariant(raw(r,['languages']),['name','language'],', '),500),
      'Prior Employer':'', 'Prior Title':'', _by:'GetLeads'
    };
    st.matched++;
  }
});
return [{ json:{ profiles, stats:st } }];

// BZ Requests: Blitz for the people GetLeads did not answer, by email only (Blitz resolves a person
// from a verified work email, not from a LinkedIn URL), one credit per answer. Only within the
// run's cap: Max Rows on the launch row, less what earlier batches already asked (the run row's
// Tally is the accumulator, read by Read Cap Row just before). A person with no email at the
// domain goes to nobody. Blank or 0 cap means Blitz is never asked.
const ctx=$('Read Records').first().json||{};
const gl=$('GL Match').first().json||{ profiles:{} };
let asked=0; try{ const prior=$('Read Cap Row').first().json; const raw=prior&&prior.fields?prior.fields.Tally:null; if(raw){ const t=JSON.parse(String(raw)); if(t&&String(t.execId)===String(ctx._execId)) asked=Number(t.blitzCalls)||0; } }catch(e){}
const cap=Math.max(0,Number(ctx._maxBlitz)||0);
let room=Math.max(0,cap-asked);
const one=(v)=>String(Array.isArray(v)?(v[0]||''):(v==null?'':v)).trim();
const norm=(d)=>one(d).toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/.*$/,'');
const splitEmails=(s)=>one(s).split(/[,;\s]+/).map(e=>e.trim().toLowerCase()).filter(e=>/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e));
const out=[]; const st={ candidates:0, noEmail:0, capped:0, cap, askedBefore:asked };
for(const i of $('Read Held').all()){
  const j=i.json||{}; if(!j.id||gl.profiles[j.id]) continue;
  st.candidates++;
  const f=j.fields||{}; const domain=norm(f.Domain);
  const emails=[one(f['Final Email']).toLowerCase()].concat(splitEmails(f.Email)).filter(e=>e&&domain&&(e.endsWith('@'+domain)||e.slice(e.lastIndexOf('@')+1).endsWith('.'+domain)));
  if(!emails.length){ st.noEmail++; continue; }
  if(room<=0){ st.capped++; continue; }
  room--;
  out.push({ json:{ id:j.id, domain, body:{ email:emails[0] } } });
}
if(!out.length) return [{ json:{ _none:true, _stats:st } }];
out[0].json._stats=st;
return out;

// BZ Match: the email-to-person answers (aligned to BZ Requests by index) -> a profile per person
// found, in the same eleven columns Enrich Contacts writes from Blitz: Headline, About, Role
// Description and Role Start Date from the current experience, Person City and Person Country from
// the location, Education and Skills joined, Prior Employer and Prior Title from the newest past
// experience. An answer is the person by construction (Blitz resolved the email we hold). Never
// throws. One item out: { profiles, stats }.
const errMsg=(e)=>{ if(!e) return 'call failed'; if(typeof e==='string') return e; return String((e.message||'')+' '+(e.description||'')).trim()||'call failed'; };
const first=$('BZ Requests').first().json||{};
const st=Object.assign({ candidates:0, noEmail:0, capped:0, cap:0, askedBefore:0 }, first._stats||{}, { called:0, found:0, notFound:0, errors:0, noCredential:0, firstError:'', failReasons:[] });
const profiles={};
if(first._none) return [{ json:{ profiles, stats:st } }];
const asks=$('BZ Requests').all().map(i=>i.json||{}).filter(j=>!j._none);
let answers=[]; try{ answers=$('BZ Email To Person').all(); }catch(e){}
const s=(v)=>String(v==null?'':v).trim();
const clip=(v,n)=>{ const t=s(v); return t.length>n?t.slice(0,n):t; };
const isoDate=(v)=>{ const m=s(v).match(/^(\d{4}-\d{2}-\d{2})/); return m?m[1]:''; };
const slugName=(u)=>{ const m=s(u).toLowerCase().match(/linkedin\.com\/company\/([^\/?#]+)/); return m?m[1].replace(/-+/g,' ').replace(/\b\w/g,ch=>ch.toUpperCase()):''; };
const joinList=(arr,sep)=>(Array.isArray(arr)?arr:[]).map(x=>typeof x==='string'?x:(x&&typeof x==='object'?s(x.name||x.language||x.title):s(x))).map(x=>x.trim()).filter(Boolean).join(sep);
const education=(arr)=>(Array.isArray(arr)?arr:[]).slice().sort((a,b)=>s((b||{}).end_date||(b||{}).start_date).localeCompare(s((a||{}).end_date||(a||{}).start_date))).map(e=>[s((e||{}).degree),s((e||{}).field_of_study),s((e||{}).school_name)].filter(Boolean).join(', ')).filter(Boolean).join('; ');
answers.forEach((it,i)=>{
  const ask=asks[i]; if(!ask) return;
  st.called++;
  const j=it.json||{};
  if(j.error&&j.body===undefined&&j.found===undefined&&j.person===undefined){
    const msg=errMsg(j.error);
    if(/credential/i.test(msg)){ st.noCredential++; return; }
    st.errors++; const r='Blitz email-to-person: '+msg.slice(0,160); if(!st.firstError) st.firstError=r; if(st.failReasons.length<10) st.failReasons.push(r); return;
  }
  const b=(j.body!==undefined)?j.body:j;
  const status=Number(j.statusCode)||200;
  if(status===404||b.found===false){ st.notFound++; return; }
  if(status>=300||!b||typeof b!=='object'){ st.errors++; const r='Blitz email-to-person HTTP '+status+' '+JSON.stringify(b).slice(0,120); if(!st.firstError) st.firstError=r; if(st.failReasons.length<10) st.failReasons.push(r); return; }
  const p=(b.person&&typeof b.person==='object')?b.person:b;
  const exps=(Array.isArray(p.experiences)?p.experiences:[]).filter(e=>e&&typeof e==='object');
  const here=exps.find(e=>e.job_is_current)||exps[0]||{};
  const past=exps.filter(e=>e!==here&&(e.job_is_current===false||e.job_end_date)).sort((a,c)=>s(c.job_end_date).localeCompare(s(a.job_end_date)));
  const prior=past[0]||{};
  const loc=(p.location&&typeof p.location==='object')?p.location:{};
  profiles[ask.id]={
    'Headline':clip(p.headline,500), 'About':clip(p.about_me,10000), 'Role Description':clip(here.job_description,10000), 'Role Start Date':isoDate(here.job_start_date),
    'Person City':clip(loc.city,120), 'Person Country':clip(loc.country_code,8).toUpperCase(),
    'Education':clip(education(p.education),2000), 'Skills':clip(joinList(p.skills,', '),2000), 'Languages':clip(joinList(p.languages,', '),500),
    'Prior Employer':clip(s(prior.company_name)||slugName(prior.company_linkedin_url),200), 'Prior Title':clip(prior.job_title,200), _by:'Blitz'
  };
  st.found++;
});
return [{ json:{ profiles, stats:st } }];

// Merge: the profiles against what each held row already carries. Same rule as Enrich Contacts: a
// held value stands, a blank is filled, nothing is overwritten, a blank never travels. GetLeads'
// profile first, Blitz's fills what is still blank. One item per row that changes, {id, fields};
// the first carries _stats; {_empty} when nothing changed.
const ctx=$('Read Records').first().json||{};
const PROFILE=Array.isArray(ctx._profileFields)&&ctx._profileFields.length?ctx._profileFields:['Headline','About','Role Description','Role Start Date','Person City','Person Country','Education','Skills','Languages','Prior Employer','Prior Title'];
const gl=$('GL Match').first().json||{ profiles:{}, stats:{} };
let bz={ profiles:{}, stats:{} }; try{ bz=$('BZ Match').first().json||bz; }catch(e){}
const one=(v)=>String(Array.isArray(v)?(v[0]||''):(v==null?'':v)).trim();
const st={ rows:0, answered:0, unanswered:0, filled:0, cells:0, byGetLeads:0, byBlitz:0, gl:gl.stats||{}, bz:bz.stats||{} };
const out=[];
for(const i of $('Read Held').all()){
  const j=i.json||{}; if(!j.id) continue;
  st.rows++;
  const f=j.fields||{};
  const sources=[gl.profiles[j.id], bz.profiles[j.id]].filter(Boolean);
  if(!sources.length){ st.unanswered++; continue; }
  st.answered++;
  const changes={}; let by='';
  for(const k of PROFILE){
    if(one(f[k])) continue;
    for(const src of sources){ let v=String(src[k]==null?'':src[k]).trim(); if(k==='Role Start Date'&&!/^\d{4}-\d{2}-\d{2}$/.test(v)) v=''; if(v){ changes[k]=v; by=by||src._by; break; } }
  }
  const n=Object.keys(changes).length;
  if(!n) continue;
  st.filled++; st.cells+=n; if(by==='Blitz') st.byBlitz++; else st.byGetLeads++;
  out.push({ json:Object.assign({ id:j.id }, changes) });
}
if(!out.length) return [{ json:{ _empty:true, _stats:st } }];
out[0].json._stats=st;
return out;

// Chunk Rows: the write rows in tens, one item per Airtable request, PATCHed as {records:[{id,
// fields}], typecast:true} 200 ms apart. Ids and size ride on the item for the count-back;
// carriers are stripped.
const rows=$input.all().map(i=>i.json).filter(j=>j&&j.id&&!j._empty);
const out=[];
for(let i=0;i<rows.length;i+=10){
  const part=rows.slice(i,i+10);
  out.push({ json:{ body:{ records:part.map(r=>{ const f={}; for(const k of Object.keys(r)){ if(k!=='id'&&k.charAt(0)!=='_') f[k]=r[k]; } return { id:String(r.id), fields:f }; }), typecast:true }, ids:part.map(r=>String(r.id)), size:part.length } });
}
if(!out.length) return [{ json:{ _none:true, size:0, ids:[] } }];
return out;

// Write Check: the writer's count-back. Written rows are counted from every 2xx answer's records[];
// a request that was not 2xx counts every row it carried as a write error and names the ids. Exactly
// one item out.
const n=(v)=>Number(v)||0;
const parse=(b)=>{ if(typeof b!=='string') return b; try{ return JSON.parse(b); }catch(e){ return null; } };
let chunks=[], resps=[];
try{ chunks=$('Chunk Rows').all().map(i=>i.json).filter(j=>!j._none); }catch(e){}
try{ resps=$('Write Rows').all(); }catch(e){}
let written=0, writeErrors=0; const failed=[], reasons=[];
const note=(ids,why)=>{ for(const id of (ids||[])){ if(failed.length<200) failed.push(id); } const w=String(why||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim().slice(0,180); if(w&&reasons.length<10) reasons.push(w); };
resps.forEach((it,i)=>{
  const c=chunks[i]||{ size:0, ids:[] }; const j=it.json||{};
  if(!c.size) return;
  if(j.error&&j.statusCode===undefined){ writeErrors+=n(c.size); note(c.ids,'row writer: '+String((j.error&&j.error.message)||j.error||'call failed')); return; }
  const status=n(j.statusCode); const b=parse(j.body===undefined?null:j.body);
  if(status>=200&&status<300&&b&&Array.isArray(b.records)){ written+=b.records.length; if(b.records.length<n(c.size)){ const back={}; for(const r of b.records) back[String((r||{}).id||'')]=1; writeErrors+=n(c.size)-b.records.length; note((c.ids||[]).filter(id=>!back[id]),(n(c.size)-b.records.length)+' of '+c.size+' records missing from a 2xx answer'); } return; }
  const e=b&&b.error; const why=e?(typeof e==='object'?(e.message||e.type||JSON.stringify(e)):String(e)):((j.error&&j.error.message)||(typeof j.body==='string'?j.body:''));
  writeErrors+=n(c.size); note(c.ids,'HTTP '+status+' '+String(why||'')+(status===429?' (rate limited; never retried)':''));
});
return [{ json:{ written, writeErrors, writeRequests:resps.length, failed, writeReasons:reasons } }];

// Build Batch Log: this batch's slice added to the run's own Hub row. The row is the accumulator
// (static data does not survive a sub-execution): Read Log Row fetched it, the totals are added,
// and the row is written back as Running; the parent writes the verdict after the last batch.
const r=$('Read Records').first().json;
const eid=String(r._execId);
const BLANK={ rows:0, answered:0, unanswered:0, filled:0, cells:0, byGetLeads:0, byBlitz:0, glCalls:0, glReturned:0, glMatched:0, glStrangers:0, glErrors:0, glNoKey:0, glBudget:false, blitzCalls:0, blitzFound:0, blitzNotFound:0, blitzErrors:0, blitzNoEmail:0, blitzCapped:0, written:0, writeErrors:0, writeWhy:[], failWhy:[], batches:0 };
let a=Object.assign({},BLANK);
try{ const prior=$('Read Log Row').first().json; const raw=prior&&prior.fields?prior.fields.Tally:null; if(raw){ const p=JSON.parse(String(raw)); if(p&&String(p.execId)===eid) a=Object.assign({},BLANK,p); } }catch(e){}
let s={}; try{ s=($('Merge').first().json||{})._stats||{}; }catch(e){}
const gl=s.gl||{}, bz=s.bz||{};
const n=(v)=>Number(v)||0;
for(const k of ['rows','answered','unanswered','filled','cells','byGetLeads','byBlitz']) a[k]+=n(s[k]);
a.glCalls+=n(gl.called); a.glReturned+=n(gl.returned); a.glMatched+=n(gl.matched); a.glStrangers+=n(gl.strangers); a.glErrors+=n(gl.errors); a.glNoKey+=n(gl.noKey); if(gl.budget) a.glBudget=true;
a.blitzCalls+=n(bz.called); a.blitzFound+=n(bz.found); a.blitzNotFound+=n(bz.notFound); a.blitzErrors+=n(bz.errors); a.blitzNoEmail+=n(bz.noEmail); a.blitzCapped+=n(bz.capped);
for(const w of (gl.failReasons||[]).concat(bz.failReasons||[])){ if(a.failWhy.length<10&&a.failWhy.indexOf(String(w))<0) a.failWhy.push(String(w)); }
try{ const wc=$('Write Check').first().json||{}; a.written+=n(wc.written); a.writeErrors+=n(wc.writeErrors); for(const w of (wc.writeReasons||[])){ if(a.writeWhy.length<10&&a.writeWhy.indexOf(String(w))<0) a.writeWhy.push(String(w)); } }catch(e){}
a.batches+=1; a.execId=eid;
const total=n(r._total);
const lines=[
  '**Running: '+a.rows+' of '+total+' people worked in '+a.batches+' batch'+(a.batches===1?'':'es')+', '+a.answered+' found, '+a.filled+' rows filled ('+a.cells+' cells), '+a.unanswered+' not found**',
  '', '**Table:** '+(r._tableName||'People')+' ('+(r._tableId||'')+') · view '+(r._view||''),
  '', '- **GetLeads:** '+a.glCalls+' lookups, '+a.glMatched+' matched, '+a.glStrangers+' strangers dropped'+(a.glErrors?', '+a.glErrors+' errors':''),
  '- **Blitz:** '+a.blitzCalls+' asked of a cap of '+n(r._maxBlitz)+', '+a.blitzFound+' found'+(a.blitzCapped?', '+a.blitzCapped+' held back by the cap':'')+(a.blitzNoEmail?', '+a.blitzNoEmail+' had no email to ask with':''),
  '- **Rows written:** '+a.written+(a.writeErrors?', '+a.writeErrors+' refused':'')
];
const row={ 'Execution ID':eid, 'Automation':'Enrich Person Profile', 'Status':'Running', 'Trigger':r._trigger||'form', 'Run at':r._startedAt, 'Target':(r._tableName||'People')+' ('+(r._tableId||'')+')', 'View':r._view||'', 'Records In':total, 'Records Out':a.written, 'Errors':a.glErrors+a.blitzErrors+a.writeErrors, 'Tally':JSON.stringify(a).slice(0,90000), 'Description':lines.join('\n'), 'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+eid };
if(r._clientId) row['Client']=[r._clientId];
return [{ json:row }];

// Batch Response: the last node of the sub-execution; its output is what the parent receives.
// Counters only, never rows.
let s={}; try{ s=($('Merge').first().json||{})._stats||{}; }catch(e){}
let w={}; try{ w=$('Write Check').first().json||{}; }catch(e){}
return [{ json:{ rows:s.rows||0, answered:s.answered||0, filled:s.filled||0, written:w.written||0, writeErrors:w.writeErrors||0 } }];
